names=[];cols=[]
for a,av in E.items():
    for k in range(5):
        names.append(a+'*T^'+str(k)); cols.append(av*T**k)
A=np.column_stack(cols)
idx=list(range(A.shape[1]))
def nm(k):
    cc,_,_,_=np.linalg.lstsq(A[:,k],sigma,rcond=None)
    return np.mean((sigma-A[:,k]@cc)**2)/np.var(sigma), cc
while len(idx)>10:
    best=None
    for j in idx:
        k=[i for i in idx if i!=j]
        e2,_=nm(k)
        if best is None or e2<best[0]: best=(e2,j)
    idx.remove(best[1])
e2,cc=nm(idx)
